<?php
$teacherId=(int)(current_user()['teacher_id']??0);
$teacher=one('SELECT * FROM teachers WHERE id=?',[$teacherId]);
if(!$teacher){echo '<div class="alert alert-error">Tài khoản chưa được liên kết với hồ sơ giảng viên.</div>';return;}
$classes=rows('SELECT s.*,b.branch_name,b.address FROM schedules s JOIN branches b ON b.id=s.branch_id WHERE s.teacher_id=? ORDER BY s.day_of_week,s.period_start',[$teacherId]);
$view=($_GET['view']??'week')==='month'?'month':'week';
$anchor=safe_date((string)($_GET['date']??date('Y-m-d')));
$monday=$anchor->modify('monday this week');
$first=$anchor->modify('first day of this month');
$prev=$view==='week'?$monday->modify('-7 days'):$first->modify('-1 month');
$next=$view==='week'?$monday->modify('+7 days'):$first->modify('+1 month');
$byDay=array_fill_keys(range(1,7),[]);
foreach($classes as $class) $byDay[(int)$class['day_of_week']][]=$class;
$periods=array_sum(array_map(static fn(array $s):int=>(int)$s['period_end']-(int)$s['period_start']+1,$classes));
?>
<div class="page-heading heading-with-action"><div><div class="eyebrow">KHÔNG GIAN GIẢNG VIÊN</div><h1>Xin chào, <?= e($teacher['full_name']) ?> <span class="heading-dot">.</span></h1><p>Lịch giảng dạy cá nhân được đồng bộ từ phòng đào tạo, lặp lại hàng tuần.</p></div><div class="personal-status"><span class="online-dot"></span> Lịch đã được cập nhật</div></div>
<div class="personal-summary"><div><span class="mini-stat-label">Số buổi / tuần</span><strong><?= count($classes) ?></strong></div><div><span class="mini-stat-label">Số tiết / tuần</span><strong><?= $periods ?></strong></div><div><span class="mini-stat-label">Cơ sở giảng dạy</span><strong><?= count(array_unique(array_column($classes,'branch_id'))) ?></strong></div><div class="personal-expertise"><small>CHUYÊN MÔN</small><strong><?= e($teacher['expertise']) ?></strong></div></div>
<section class="panel calendar-panel"><div class="calendar-toolbar"><div><h2>Thời khóa biểu của tôi</h2><p><?= $view==='week'?e(format_week($anchor)):'Tháng '.$first->format('m/Y') ?></p></div><div class="calendar-controls"><div class="seg-tabs"><a class="<?= $view==='week'?'selected':'' ?>" href="<?= e(app_url('my-schedule',['view'=>'week','date'=>$anchor->format('Y-m-d')])) ?>">Theo tuần</a><a class="<?= $view==='month'?'selected':'' ?>" href="<?= e(app_url('my-schedule',['view'=>'month','date'=>$anchor->format('Y-m-d')])) ?>">Theo tháng</a></div><a class="calendar-arrow" aria-label="Trước" href="<?= e(app_url('my-schedule',['view'=>$view,'date'=>$prev->format('Y-m-d')])) ?>">‹</a><a class="calendar-arrow" aria-label="Sau" href="<?= e(app_url('my-schedule',['view'=>$view,'date'=>$next->format('Y-m-d')])) ?>">›</a><a class="btn btn-ghost btn-sm" href="<?= e(app_url('my-schedule',['view'=>$view,'date'=>date('Y-m-d')])) ?>">Hôm nay</a></div></div>
<?php if($view==='week'): ?><div class="week-calendar"><?php for($i=0;$i<7;$i++): $date=$monday->modify('+'.$i.' days');$index=$i+1;?><div class="week-day"><div class="week-day-head<?= $date->format('Y-m-d')===date('Y-m-d')?' is-today':'' ?>"><span><?= e(short_day($index)) ?></span><strong><?= $date->format('d') ?></strong></div><div class="week-day-body"><?php foreach($byDay[$index] as $item): ?><div class="course-card"><span class="course-time"><?= e(period_label((int)$item['period_start'],(int)$item['period_end'])) ?></span><strong><?= e($item['subject_name']) ?></strong><span class="course-location">⌖ <?= e($item['branch_name']) ?></span><span class="course-room"><?= e($item['room']) ?></span></div><?php endforeach; ?><?php if(!$byDay[$index]): ?><span class="day-free">Không có lịch</span><?php endif; ?></div></div><?php endfor; ?></div>
<?php else: ?><?php $calendarStart=$first->modify('monday this week');$last=$first->modify('last day of this month');$calendarEnd=$last->modify('sunday this week');?><div class="month-calendar"><div class="month-weekhead"><?php foreach(day_names() as $day): ?><span><?= e($day) ?></span><?php endforeach; ?></div><div class="month-grid"><?php for($date=$calendarStart;$date<=$calendarEnd;$date=$date->modify('+1 day')):$index=(int)$date->format('N');?><div class="month-cell<?= $date->format('m')!==$first->format('m')?' muted':'' ?><?= $date->format('Y-m-d')===date('Y-m-d')?' is-today':'' ?>"><span class="month-date"><?= $date->format('d') ?></span><?php foreach($byDay[$index] as $item): ?><div class="month-course" title="<?= e($item['subject_name'].' · '.$item['branch_name'].' · '.period_label((int)$item['period_start'],(int)$item['period_end'])) ?>"><?= e($item['subject_name']) ?><small><?= e(period_label((int)$item['period_start'],(int)$item['period_end'])) ?></small></div><?php endforeach; ?></div><?php endfor; ?></div></div><?php endif; ?></section>
<section class="panel"><div class="panel-heading"><div><h2>Chi tiết lịch dạy</h2><p>Địa chỉ cơ sở và phòng học để thuận tiện di chuyển</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>THỨ / TIẾT</th><th>HỌC PHẦN</th><th>CƠ SỞ</th><th>ĐỊA CHỈ</th><th>PHÒNG</th></tr></thead><tbody><?php foreach($classes as $item): ?><tr><td><span class="tag-blue"><?= e(short_day((int)$item['day_of_week'])) ?></span> <?= e(period_label((int)$item['period_start'],(int)$item['period_end'])) ?></td><td><strong><?= e($item['subject_name']) ?></strong></td><td><?= e($item['branch_name']) ?></td><td><?= e($item['address']) ?></td><td><span class="room-pill"><?= e($item['room']) ?></span></td></tr><?php endforeach; ?><?php if(!$classes): ?><tr><td colspan="5" class="table-empty">Hiện chưa có lịch dạy được phân công.</td></tr><?php endif; ?></tbody></table></div></section>
